package com.oyxdsg.smartmaid.entity.ai

/**
 * Maid jump offline precise solution table (generated by tools/gen_jump_table.js, do not edit).
 *
 * For each scenario (horizontal feet displacement dist x height diff dy) the safe takeoff
 * solution is precomputed: {sprint: walk/sprint tier, back: takeoff-point retreat from edge}.
 * The mod only looks up the table at runtime; no physics computation in-game.
 *
 * Physics: prismarine-physics (vanilla), MOVEMENT_SPEED=0.16,
 * vy0=0.42 max rise ~1.25 blocks, airborne continuous-forward input (+0.02/tick).
 */
object MaidJumpTable {

    /** Jump solution: sprint = sprint tier, back = takeoff-point retreat (blocks) */
    @JvmRecord
    data class JumpSolution(val sprint: Boolean, val back: Double)

    private val TABLE = arrayOfNulls<JumpSolution>(40)

    private fun put(dist: Int, dy: Int, s: JumpSolution) {
        TABLE[dist * 8 + (dy + 3)] = s
    }

    init {
        put(2, -3, JumpSolution(false, 1.25))
        put(2, -2, JumpSolution(false, 1.25))
        put(2, -1, JumpSolution(false, 1.25))
        put(2, 0, JumpSolution(false, 1.25))
        put(2, 1, JumpSolution(false, 0.00))
        put(3, -3, JumpSolution(false, 0.25))
        put(3, -2, JumpSolution(false, 0.25))
        put(3, -1, JumpSolution(false, 0.25))
        put(3, 0, JumpSolution(false, 0.25))
        put(3, 1, JumpSolution(false, 0.00))
        put(4, -3, JumpSolution(false, 0.00))
        put(4, -2, JumpSolution(false, 0.00))
        put(4, -1, JumpSolution(false, 0.00))
        put(4, 0, JumpSolution(true, 1.25))
        put(4, 1, JumpSolution(true, 0.00))
    }

    /** Look up the jump solution for scenario (dist, dy); null if unsolvable. */
    @JvmStatic
    fun get(dist: Int, dy: Int): JumpSolution? {
        if (dist < 2 || dist > 4 || dy < -3 || dy > 1) {
            return null
        }
        return TABLE[dist * 8 + (dy + 3)]
    }
}
